const { inspectTemplate } = require('./panel-template-instrumentation')
const { compatibleTarget, controlTypeForAdapter, targetMeta } = require('./control-type-model')
const { meterRoute } = require('./meter-route')
const { xySeriesRoute } = require('./xy-series-route')

const ID = /^[A-Za-z][A-Za-z0-9._/-]{0,127}$/
const INSTANCE_KEY = /^[A-Za-z0-9._:/-]{1,160}$/
const MODES = new Set(['read', 'write', 'both'])

function buttonBehavior (entry, candidate) {
  const behavior = entry.buttonBehavior ?? 'toggle'
  if (!['toggle', 'momentary'].includes(behavior) ||
    (entry.buttonBehavior !== undefined && !candidate.button) ||
    (behavior === 'momentary' && entry.mode !== 'both')) {
    throw new Error('Button behavior requires a boolean button; momentary buttons require both mode')
  }
  return behavior
}

function targetKey (candidate, entry) {
  if (!candidate.repeat) return candidate.locator
  if (typeof entry.instanceKey !== 'string' || !INSTANCE_KEY.test(entry.instanceKey)) {
    throw new Error('Repeated visual controls need a stable instance key')
  }
  if (candidate.repeat.kind === 'array' && !/^(0|[1-9][0-9]*)$/.test(entry.instanceKey)) {
    throw new Error('Array repeated controls need a non-negative integer instance key')
  }
  return `${candidate.locator}#${entry.instanceKey}`
}

function parseVisualBindings (config) {
  let raw = config.visualBindings || '{}'
  if (typeof raw === 'string') raw = JSON.parse(raw)
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('Invalid visual bindings')
  return raw
}

function visualRoutes (config) {
  const saved = parseVisualBindings(config)
  const candidates = inspectTemplate(config.format).candidates
  const locators = new Map(candidates.filter(item => item.supported).map(item => [item.locator, item]))
  const routes = new Map()
  const usedLocators = new Set()
  for (const [id, entry] of Object.entries(saved)) {
    if (!ID.test(id) || !entry || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new Error(`Invalid visual control: ${id}`)
    }
    const candidate = locators.get(entry.locator)
    if (!candidate || candidate.adapter !== entry.adapter) {
      throw new Error(`Visual control moved or became ambiguous: ${id}`)
    }
    const bindingKey = targetKey(candidate, entry)
    const behavior = buttonBehavior(entry, candidate)
    if (behavior === 'momentary' && !['mute', 'power'].includes(entry.type)) {
      throw new Error('Momentary buttons require a boolean control type')
    }
    if (usedLocators.has(bindingKey)) throw new Error(`Duplicate visual control locator: ${id}`)
    usedLocators.add(bindingKey)
    if (!MODES.has(entry.mode) || !entry.type || !entry.label ||
      (['meter', 'xy-series', 'text-display'].includes(entry.adapter) && entry.mode !== 'read')) {
      throw new Error(`Invalid visual binding settings: ${id}`)
    }
    if (entry.readMeta?.meter) {
      meterRoute(entry.readMeta.meter)
      if (entry.adapter !== 'meter' || entry.mode !== 'read' || entry.readMeta.access !== 'ro' ||
        !['integer', 'float'].includes(entry.readMeta.type) ||
        !Number.isFinite(entry.readMeta.min) || !Number.isFinite(entry.readMeta.max) ||
        entry.readMeta.min >= entry.readMeta.max) throw Error(`Invalid meter binding: ${id}`)
    }
    if (entry.readMeta?.xySeries) {
      xySeriesRoute(entry.readMeta.xySeries)
      if (entry.adapter !== 'xy-series' || entry.mode !== 'read' || entry.readMeta.access !== 'ro') {
        throw Error(`Invalid xy-series binding: ${id}`)
      }
    }
    routes.set(id, {
      control: { id, type: entry.type, mode: entry.mode, label: entry.label,
        adapter: entry.adapter, locator: entry.locator,
        ...(candidate.button ? { buttonBehavior: behavior } : {}),
        ...(candidate.repeat ? { instanceKey: entry.instanceKey } : {}) },
      binding: entry
    })
  }
  return routes
}

function validatedVisualBindings ({ format, entries, devices, targetsByDevice }) {
  if (!Array.isArray(entries) || entries.length > 256) throw new Error('At most 256 visual bindings are supported')
  const candidates = new Map(inspectTemplate(format).candidates
    .filter(item => item.supported).map(item => [item.locator, item]))
  const knownDevices = new Map(devices.map(device => [device.id, device]))
  const result = Object.create(null)
  const used = new Set()
  const usedLocators = new Set()
  const models = new Map()
  for (const raw of entries) {
    if (!raw || !ID.test(raw.id) || used.has(raw.id)) throw new Error('Control IDs must be unique and valid')
    used.add(raw.id)
    const candidate = candidates.get(raw.locator)
    if (!candidate || candidate.adapter !== raw.adapter) throw new Error(`Control changed: ${raw.id}`)
    const bindingKey = targetKey(candidate, raw)
    const behavior = buttonBehavior(raw, candidate)
    if (usedLocators.has(bindingKey)) throw new Error(`One element cannot have two bindings: ${raw.id}`)
    usedLocators.add(bindingKey)
    if (!MODES.has(raw.mode) || (['meter', 'xy-series', 'text-display'].includes(raw.adapter) && raw.mode !== 'read')) {
      throw new Error(`Invalid binding mode: ${raw.id}`)
    }
    if (typeof raw.label !== 'string' || !raw.label.trim() || raw.label.length > 80) {
      throw new Error(`Invalid control label: ${raw.id}`)
    }
    if (!knownDevices.has(raw.device)) throw new Error(`Unknown device: ${raw.id}`)
    const targets = targetsByDevice.get(raw.device)
    if (!targets) throw new Error(`Device catalog unavailable: ${raw.device}`)
    const byPath = new Map(targets.map(target => [target.path, target]))
    const write = raw.mode === 'read' ? null : byPath.get(raw.writePath)
    const read = raw.mode === 'write' ? null : byPath.get(raw.readPath)
    if ((raw.mode !== 'read' && !write) || (raw.mode !== 'write' && !read)) {
      throw new Error(`Target disappeared: ${raw.id}`)
    }
    if (write && !compatibleTarget(raw.adapter, write, 'write', candidate)) throw new Error(`Incompatible write target: ${raw.id}`)
    if (read && !compatibleTarget(raw.adapter, read, 'read', candidate)) throw new Error(`Incompatible feedback target: ${raw.id}`)
    if (write && read && controlTypeForAdapter(raw.adapter, write) !== controlTypeForAdapter(raw.adapter, read)) {
      throw new Error(`Read and write targets have different types: ${raw.id}`)
    }
    const target = write || read
    const type = controlTypeForAdapter(raw.adapter, target)
    if (read?.meter && (!Number.isFinite(read.min) || !Number.isFinite(read.max) || read.min >= read.max)) {
      throw Error(`Meter needs a finite device range: ${raw.id}`)
    }
    if (candidate.model) {
      const identity = JSON.stringify([raw.device, read?.path, write?.path])
      const modelKey = candidate.repeat ? `${candidate.model}#${raw.instanceKey}` : candidate.model
      const previous = models.get(modelKey)
      if (previous && (read?.meter || previous.meter) && previous.identity !== identity) {
        throw Error(`Meter model "${candidate.model}" is already used by another binding; use a separate Vue model for the meter. Meter and volume controls must not share a model`)
      }
      models.set(modelKey, { identity, meter: Boolean(read?.meter) })
    }
    result[raw.id] = {
      locator: raw.locator, adapter: raw.adapter, type, label: raw.label.trim(), mode: raw.mode,
      ...(candidate.button ? { buttonBehavior: behavior } : {}),
      ...(candidate.model ? { model: candidate.model } : {}),
      ...(candidate.repeat ? { repeat: candidate.repeat, instanceKey: raw.instanceKey } : {}),
      ...(candidate.component ? { component: candidate.component } : {}),
      ...(['range', 'meter'].includes(raw.adapter)
        ? { uiRange: { min: candidate.min, max: candidate.max, step: candidate.step } } : {}),
      device: raw.device,
      writePath: write?.path || '', readPath: read?.path || '',
      ...(write ? { writeMeta: targetMeta(write, raw.onebased) } : {}),
      ...(read ? { readMeta: targetMeta(read, raw.onebased) } : {})
    }
  }
  return result
}

module.exports = { parseVisualBindings, visualRoutes, validatedVisualBindings }
